package com.vajjha.recipes.model;import jakarta.persistence.*;import java.time.Instant;@Entity @Table(name="recipe_categories") public class RecipeCategory{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,unique=true)private String name;@Column(nullable=false,unique=true)private String slug;private String description;private String accent;@Column(name="created_at")private Instant createdAt;public Long getId(){return id;}public String getName(){return name;}public String getSlug(){return slug;}public String getDescription(){return description;}public String getAccent(){return accent;}}